impl<T: gx::Real> Scalar<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (4 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Scalar<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t1 * t3;
        Scalar::from_coeffs([t4])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Scalar::from_coeffs([t0]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Scalar::from_coeffs(c).normalized()
    }

}

impl<T: gx::Coef> gx::NewtonStep for Scalar<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t3 = x[0] * T::from_ratio(3, 2);
        let t4 = (-t1).mul_add(T::from_ratio(1, 2), t3);
        Scalar::from_coeffs([t4])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

#[doc = "A vector: a point `x + Â½xÂ² ei + eo`, a circle or a line (dual representation). As a versor it is a reflection in a line or an inversion in a circle."]
///
/// Blades, in coefficient order: `[e1, e2, eo, ei]`.
///
/// `S` lists the open slots: `Vector` (that is, `Vector<()>`) is a value, `Vector<(A,)>` a
/// linear map from `A`, `Vector<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Vector<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 4],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Vector<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Vector<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Vector<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Vector<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Vector");
        for (b, c) in <Vector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Vector {
    const N: usize = 4;
    const NAME: &'static str = "Vector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e1", "e2", "eo", "ei"];
    type Arr<X: gx::Elem> = [X; 4];
    type Mv<S: gx::Slots, T: gx::Coef> = Vector<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 4] {
        [f(0), f(1), f(2), f(3)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 4], mut f: impl FnMut(&X) -> Y) -> [Y; 4] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 4],
        b: &[Y; 4],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 4] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3])]
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::Extensor for Vector<S, T> {
    type Kind = Vector;
    type Slots = S;
    type Coef = T;
    #[inline(always)]
    fn from_coeffs(c: [S::Arr<T>; 4]) -> Self {
        Vector { c }
    }
    #[inline(always)]
    fn coeffs(&self) -> &[S::Arr<T>; 4] {
        &self.c
    }
}

