        let m8 = v[3] * v[3];
        let m9 = m0 - m1;
        let m10 = m0 + m1;
        let m11 = v[2].mul_add(v[2], m8);
        let m12 = m11 * T::from_i64(2);
        let m13 = -m12;
        let m14 = m4 + m5;
        let m15 = m14 * T::from_i64(2);
