        let m21 = m2 * T::from_i64(2);
        let m22 = m3 + m6;
        let m23 = m22 * T::from_i64(2);
        let m24 = -m23;
        let m25 = -m21;
        gx::Prepared::from_entries([m10, m13, m16, m18, m20, m9, m21, m24, m25])
