impl gx::batch::SandwichKernel<Multivector, gx::batch::Plain> for Motor {
    type Y = Multivector;
    type Versor<T: gx::Coef> = Motor<(), T>;
    type Prepared<T: gx::Coef> = gx::Prepared<Motor, Multivector, T, 17>;
    #[inline(always)]
    fn wrap<T: gx::Coef>(v: Motor<(), T>) -> Motor<(), T> {
        v
    }
    #[inline(always)]
    fn unwrap<T: gx::Coef>(v: Motor<(), T>) -> Motor<(), T> {
        v
    }
    #[inline(always)]
    fn prepare<T: gx::Coef>(v: Motor<(), T>) -> gx::Prepared<Motor, Multivector, T, 17> {
        gx::Prepare::<Multivector>::prepare(v)
    }
    #[inline(always)]
    fn map_prepared<T: gx::Coef, W: gx::Coef>(p: gx::Prepared<Motor, Multivector, T, 17>, mut f: impl FnMut(T) -> W) -> gx::Prepared<Motor, Multivector, W, 17> {
        let m = p.m;
        gx::Prepared::from_entries([f(m[0]), f(m[1]), f(m[2]), f(m[3]), f(m[4]), f(m[5]), f(m[6]), f(m[7]), f(m[8]), f(m[9]), f(m[10]), f(m[11]), f(m[12]), f(m[13]), f(m[14]), f(m[15]), f(m[16])])
    }
    #[inline(always)]
    fn apply_prepared<T: gx::Coef>(p: gx::Prepared<Motor, Multivector, T, 17>, x: Multivector<(), T>) -> Multivector<(), T> {
        gx::Transform::transform(p, x)
    }
    #[inline(always)]
    fn apply<T: gx::Coef>(v: Motor<(), T>, x: Multivector<(), T>) -> Multivector<(), T> {
        gx::Transform::transform(v, x)
    }
}

