#[cfg(feature = "batch")]
impl gx::batch::SandwichKernel<Odd, gx::batch::Plain> for Even {
    type Y = Odd;
    type Versor<T: gx::Coef> = Even<(), T>;
    type Prepared<T: gx::Coef> = gx::Prepared<Even, Odd, T, 24>;
    #[inline(always)]
    fn wrap<T: gx::Coef>(v: Even<(), T>) -> Even<(), T> {
        v
    }
    #[inline(always)]
    fn unwrap<T: gx::Coef>(v: Even<(), T>) -> Even<(), T> {
        v
    }
    #[inline(always)]
    fn prepare<T: gx::Coef>(v: Even<(), T>) -> gx::Prepared<Even, Odd, T, 24> {
        gx::Prepare::<Odd>::prepare(v)
    }
    #[inline(always)]
    fn map_prepared<T: gx::Coef, W: gx::Coef>(p: gx::Prepared<Even, Odd, T, 24>, mut f: impl FnMut(T) -> W) -> gx::Prepared<Even, Odd, W, 24> {
        let m = p.m;
        gx::Prepared::from_entries([f(m[0]), f(m[1]), f(m[2]), f(m[3]), f(m[4]), f(m[5]), f(m[6]), f(m[7]), f(m[8]), f(m[9]), f(m[10]), f(m[11]), f(m[12]), f(m[13]), f(m[14]), f(m[15]), f(m[16]), f(m[17]), f(m[18]), f(m[19]), f(m[20]), f(m[21]), f(m[22]), f(m[23])])
    }
    #[inline(always)]
    fn apply_prepared<T: gx::Coef>(p: gx::Prepared<Even, Odd, T, 24>, x: Odd<(), T>) -> Odd<(), T> {
        gx::Transform::transform(p, x)
    }
    #[inline(always)]
    fn apply<T: gx::Coef>(v: Even<(), T>, x: Odd<(), T>) -> Odd<(), T> {
        gx::Transform::transform(v, x)
    }
}

