#[cfg(feature = "batch")]
impl gx::batch::SandwichKernel<Twist, gx::batch::Certified> for Odd {
    type Y = Bivector;
    type Versor<T: gx::Coef> = gx::Unit<Odd<(), T>>;
    type Prepared<T: gx::Coef> = gx::Prepared<gx::Unit<Odd>, Twist, T, 15>;
    #[inline(always)]
    fn wrap<T: gx::Coef>(v: Odd<(), T>) -> gx::Unit<Odd<(), T>> {
        gx::Unit::new_unchecked(v)
    }
    #[inline(always)]
    fn unwrap<T: gx::Coef>(v: gx::Unit<Odd<(), T>>) -> Odd<(), T> {
        v.into_inner()
    }
    #[inline(always)]
    fn prepare<T: gx::Coef>(v: gx::Unit<Odd<(), T>>) -> gx::Prepared<gx::Unit<Odd>, Twist, T, 15> {
        gx::Prepare::<Twist>::prepare(v)
    }
    #[inline(always)]
    fn map_prepared<T: gx::Coef, W: gx::Coef>(p: gx::Prepared<gx::Unit<Odd>, Twist, T, 15>, mut f: impl FnMut(T) -> W) -> gx::Prepared<gx::Unit<Odd>, Twist, W, 15> {
        let m = p.m;
        gx::Prepared::from_entries([f(m[0]), f(m[1]), f(m[2]), f(m[3]), f(m[4]), f(m[5]), f(m[6]), f(m[7]), f(m[8]), f(m[9]), f(m[10]), f(m[11]), f(m[12]), f(m[13]), f(m[14])])
    }
    #[inline(always)]
    fn apply_prepared<T: gx::Coef>(p: gx::Prepared<gx::Unit<Odd>, Twist, T, 15>, x: Twist<(), T>) -> Bivector<(), T> {
        gx::Transform::transform(p, x)
    }
    #[inline(always)]
    fn apply<T: gx::Coef>(v: gx::Unit<Odd<(), T>>, x: Twist<(), T>) -> Bivector<(), T> {
        gx::Transform::transform(v, x)
    }
}

